def load() -> pd.DataFrame:
    import glob
    files = glob.glob('data/environment/input/water-body-testing-*.csv')
    dfs = []
    for file in sorted(files):
        df = pd.read_csv(file)
        dfs.append(df)
    return pd.concat(dfs, ignore_index=True)

def process(normalize_violations) -> pd.DataFrame:
    df = normalize_violations
    total_tests = len(df)
    violation_tests = len(df[df['Violation'] == 'yes'])
    exceedance_rate = (violation_tests / total_tests) * 100 if total_tests > 0 else 0
    return pd.DataFrame({'exceedance_rate': [round(exceedance_rate, 2)]})
